1	import { useState, useEffect, useMemo } from "react";
2	import {
3	  useListAssets, useCreateAsset, useUpdateAsset, useDeleteAsset, useAiEnhanceAsset,
4	  useGetProject, useUpdateProject, getListAssetsQueryKey, getGetProjectQueryKey,
5	  useListEntities, useCreateEntity, useUpdateEntity, useDeleteEntity,
6	  useAiGenerateEntities, useAiEnhanceEntity,
7	  useListEntityProperties, useCreateEntityProperty, useUpdateEntityProperty, useDeleteEntityProperty,
8	  getListEntitiesQueryKey, getListEntityPropertiesQueryKey,
9	  type Asset, type AssetEnhanceSuggestion, type Entity, type EntityProperty,
10	} from "@workspace/api-client-react";
11	import { useQueryClient } from "@tanstack/react-query";
12	import {
13	  Plus, Trash2, ImageIcon, Edit2, Sparkles, Download, Loader2, Wand2, Save, BookOpen,
14	  Layers, Square, Circle, Dice5, User, Map as MapIcon, Package, Tag, Check, X, RefreshCw,
15	  ChevronDown, ChevronRight, Settings, Pencil, Copy, FileText,
16	} from "lucide-react";
17	import { Button } from "@/components/ui/button";
18	import { Card, CardContent } from "@/components/ui/card";
19	import { Input } from "@/components/ui/input";
20	import { Textarea } from "@/components/ui/textarea";
21	import { Label } from "@/components/ui/label";
22	import {
23	  Select, SelectContent, SelectItem, SelectTrigger, SelectValue,
24	  SelectGroup, SelectLabel,
25	} from "@/components/ui/select";
26	import { Skeleton } from "@/components/ui/skeleton";
27	import { Badge } from "@/components/ui/badge";
28	import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription, DialogFooter } from "@/components/ui/dialog";
29	import { useToast } from "@/hooks/use-toast";
30	
31	// ── Component type constants ──────────────────────────────────────────────────
32	
33	const PHYSICAL_TYPES = ["Card", "Deck", "Token", "Die", "Tile", "Meeple", "Board"] as const;
34	const WORLD_TYPES    = ["Location", "Faction", "Event", "Resource", "Ability"] as const;
35	const ALL_COMPONENT_TYPES = [...PHYSICAL_TYPES, ...WORLD_TYPES] as const;
36	type ComponentType = typeof ALL_COMPONENT_TYPES[number];
37	
38	const COMPONENT_META: Record<ComponentType, { icon: string; color: string; bg: string; badge: string; desc: string }> = {
39	  Card:     { icon: "🃏", color: "text-violet-400",  bg: "bg-violet-500/5",  badge: "bg-violet-500/20 text-violet-400 border-violet-500/30",  desc: "Action, item, spell, event, treasure cards" },
40	  Deck:     { icon: "📦", color: "text-indigo-400",  bg: "bg-indigo-500/5",  badge: "bg-indigo-500/20 text-indigo-400 border-indigo-500/30",  desc: "Collection of cards (container)" },
41	  Token:    { icon: "🪙", color: "text-amber-400",   bg: "bg-amber-500/5",   badge: "bg-amber-500/20 text-amber-400 border-amber-500/30",     desc: "Resource, currency, health, status markers" },
42	  Die:      { icon: "🎲", color: "text-red-400",     bg: "bg-red-500/5",     badge: "bg-red-500/20 text-red-400 border-red-500/30",           desc: "Custom die type or face set" },
43	  Tile:     { icon: "🗺️", color: "text-emerald-400", bg: "bg-emerald-500/5", badge: "bg-emerald-500/20 text-emerald-400 border-emerald-500/30", desc: "Map, dungeon, terrain tiles" },
44	  Meeple:   { icon: "🧩", color: "text-blue-400",    bg: "bg-blue-500/5",    badge: "bg-blue-500/20 text-blue-400 border-blue-500/30",        desc: "Pawn, figure, standee, miniature" },
45	  Board:    { icon: "📋", color: "text-slate-400",   bg: "bg-slate-500/5",   badge: "bg-slate-500/20 text-slate-400 border-slate-500/30",     desc: "Game board, player mat, reference sheet" },
46	  Location: { icon: "📍", color: "text-cyan-400",    bg: "bg-cyan-500/5",    badge: "bg-cyan-500/20 text-cyan-400 border-cyan-500/30",        desc: "City, dungeon, region, landmark" },
47	  Faction:  { icon: "⚔️", color: "text-purple-400",  bg: "bg-purple-500/5",  badge: "bg-purple-500/20 text-purple-400 border-purple-500/30",  desc: "Guild, tribe, nation, team" },
48	  Event:    { icon: "⚡", color: "text-orange-400",  bg: "bg-orange-500/5",  badge: "bg-orange-500/20 text-orange-400 border-orange-500/30",  desc: "Random event, scenario, story beat" },
49	  Resource: { icon: "💎", color: "text-teal-400",    bg: "bg-teal-500/5",    badge: "bg-teal-500/20 text-teal-400 border-teal-500/30",        desc: "Material, food, energy, mana" },
50	  Ability:  { icon: "✨", color: "text-pink-400",    bg: "bg-pink-500/5",    badge: "bg-pink-500/20 text-pink-400 border-pink-500/30",        desc: "Passive, active, triggered, ultimate" },
51	};
52	
53	const COMPONENT_SUBTYPES: Record<ComponentType, string[]> = {
54	  Card:     ["Action", "Item", "Spell", "Event", "Quest", "Encounter", "Treasure", "Attack", "Defense"],
55	  Deck:     ["Item Deck", "Event Deck", "Encounter Deck", "Spell Deck", "Quest Deck", "Custom"],
56	  Token:    ["Resource", "Currency", "Health", "Status", "Marker", "Victory Point", "Damage"],
57	  Die:      ["Action Die", "Combat Die", "Event Die", "Skill Die", "Custom"],
58	  Tile:     ["Map Tile", "Dungeon Tile", "Terrain", "Room", "Hex", "Starting Tile"],
59	  Meeple:   ["Pawn", "Figure", "Standee", "Miniature", "Marker", "Ship", "Vehicle"],
60	  Board:    ["Main Board", "Player Board", "Map", "Reference Sheet", "Expansion Board"],
61	  Location: ["City", "Dungeon", "Region", "Shop", "Quest Site", "Landmark", "Lair"],
62	  Faction:  ["Guild", "Tribe", "Nation", "Team", "House", "Order", "Corporation"],
63	  Event:    ["Random Event", "Scenario", "Story Beat", "Encounter", "World Event", "Trigger"],
64	  Resource: ["Currency", "Material", "Food", "Energy", "Mana", "Influence", "Faith"],
65	  Ability:  ["Passive", "Active", "Triggered", "Ultimate", "Reaction", "Aura"],
66	};
67	
68	function getMeta(type: string) {
