110	  return `Please generate a Gamma PDF presentation for my board game deck.
111	
112	**Game:** ${projectName}
113	**Narrative:** ${narrative || "(none)"}
114	
115	**Deck:** ${deck.name}${deck.subtype ? ` (${deck.subtype})` : ""}
116	**Description:** ${deck.description || "(none)"}${deck.lore ? `\n**Flavor/Lore:** ${deck.lore}` : ""}${deck.designNotes ? `\n**Designer Notes:** ${deck.designNotes}` : ""}
