375	  const refresh = () => qc.invalidateQueries({ queryKey: getListAssetsQueryKey(projectId) });
376	
377	  const composedPrompt = (kind: ComponentKind, extra?: string) => {
378	    const narr = narrative.trim() || projectDescription || "a tabletop game";
