380	    const entityLine = entityNames.length ? `Featuring: ${entityNames.join(", ")}.` : "";
381	    const prompt = `Design ${kind.promptHint} for "${projectName}". Narrative: ${narr}. ${entityLine} Style: hand-painted, rich color, professional board-game art.${extra ? " " + extra : ""}`;
382	    return {
383	      prompt,
384	      assetName: `${kind.label}: ${narr.split(/\s+/).slice(0, 4).join(" ")}`.slice(0, 60),
385	      description: `${kind.label} — ${narr.slice(0, 140)}`,
386	      tag: kind.label,
387	    };
