390	  const generateImageDirect = async (assetId: number, prompt: string) => {
391	    const base = import.meta.env.BASE_URL.replace(/\/$/, "");
392	    const res = await fetch(`${base}/api/projects/${projectId}/assets/${assetId}/generate-image`, {
393	      method: "POST",
394	      headers: { "Content-Type": "application/json" },
