410	      refresh();
411	      const ok = await generateImageDirect(created.id, c.prompt);
412	      refresh();
413	      toast({ title: ok ? `${tile.label} generated` : "Image failed — asset created", variant: ok ? "default" : "destructive" });
414	    } catch (err) {
415	      toast({ title: "Generation failed", description: err instanceof Error ? err.message : String(err), variant: "destructive" });
416	    } finally {
417	      setGeneratingTile(null);
418	    }
419	  };
420	
421	  const generateFromFreeform = async () => {
422	    const txt = freeformPrompt.trim();
423	    if (!txt) return;
424	    setGeneratingFreeform(true);
425	    try {
426	      const narr = narrative.trim() || projectDescription || "";
427	      const fullPrompt = narr ? `${txt}. Narrative: ${narr}. Style: hand-painted, professional board-game art.` : txt;
428	      const created = await createAsset.mutateAsync({ projectId, data: { name: txt.slice(0, 60), kind: "other", description: `Custom — ${txt}`.slice(0, 240), flavorText: "Custom" } });
429	      refresh();
430	      const ok = await generateImageDirect(created.id, fullPrompt);
431	      refresh();
432	      if (ok) { toast({ title: "Asset generated" }); setFreeformPrompt(""); }
433	      else toast({ title: "Image generation failed", variant: "destructive" });
434	    } catch (err) {
435	      toast({ title: "Generation failed", description: err instanceof Error ? err.message : String(err), variant: "destructive" });
436	    } finally {
437	      setGeneratingFreeform(false);
438	    }
439	  };
440	
441	  const generateImage = async (assetId: number, prompt: string) => {
442	    setGenerating(assetId);
443	    try {
444	      if (!await generateImageDirect(assetId, prompt)) throw new Error("gen failed");
445	      refresh(); toast({ title: "Image generated" });
446	    } catch {
447	      toast({ title: "Generation failed", variant: "destructive" });
448	    } finally {
449	      setGenerating(null);
450	    }
451	  };
452	
453	  const openImagePrompt = (id: number) => {
454	    const a = assets?.find((x) => x.id === id);
455	    setImagePrompt(a?.imagePrompt || `${a?.name} ${a?.description || ""}`.trim());
456	    setImagePromptId(id);
