493	            <div className="flex justify-end gap-2">
494	              <Button variant="outline" size="sm" onClick={() => { setImagePromptId(null); setImagePrompt(""); }}>Cancel</Button>
495	              <Button size="sm" className="gap-1.5" onClick={() => { generateImage(imagePromptId!, imagePrompt); setImagePromptId(null); setImagePrompt(""); }} disabled={!imagePrompt.trim()}>
496	                <Sparkles className="h-3.5 w-3.5" /> Generate
497	              </Button>
498	            </div>
499	          </CardContent>
500	        </Card>
501	      )}
502	
503	      {/* Quick-generate tiles */}
504	      <div>
505	        <h3 className="text-xs font-semibold uppercase tracking-wider text-muted-foreground mb-3">Quick generate</h3>
