508	            const Icon = tile.icon;
509	            const busy = generatingTile === tile.id;
510	            return (
511	              <button
512	                key={tile.id}
513	                onClick={() => generateFromTile(tile)}
514	                disabled={busy || !!generatingTile}
515	                className="flex flex-col items-center gap-2 p-4 rounded-lg border border-border bg-card hover:border-primary/50 hover:bg-primary/5 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
516	              >
