518	                <span className="text-xs font-medium">{tile.label}</span>
519	              </button>
520	            );
521	          })}
522	        </div>
523	      </div>
524	
525	      {/* Freeform */}
526	      <Card className="bg-card border-card-border">
527	        <CardContent className="p-3">
528	          <div className="flex gap-2">
529	            <Input
530	              placeholder="Describe a custom component…"
531	              value={freeformPrompt}
532	              onChange={(e) => setFreeformPrompt(e.target.value)}
533	              onKeyDown={(e) => { if (e.key === "Enter" && !generatingFreeform) generateFromFreeform(); }}
534	            />
535	            <Button onClick={generateFromFreeform} disabled={!freeformPrompt.trim() || generatingFreeform} className="gap-1.5 shrink-0">
536	              {generatingFreeform ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <Wand2 className="h-3.5 w-3.5" />} Generate
537	            </Button>
538	          </div>
539	        </CardContent>
540	      </Card>
541	
542	      {/* Asset grid */}
543	      {isLoading ? (
544	        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
