680	function AssetCard({
681	  asset, entities, projectId, isGenerating,
682	  onGenerateImage, onDownload, onDelete, onUpdated, fetchEnhance, applyEnhance, onGamma,
683	}: {
684	  asset: Asset;
685	  entities: Entity[];
686	  projectId: number;
687	  isGenerating: boolean;
688	  onGenerateImage: () => void;
689	  onDownload: () => void;
690	  onDelete: () => Promise<void>;
691	  onUpdated: () => void;
692	  fetchEnhance: () => Promise<AssetEnhanceSuggestion>;
693	  applyEnhance: (fields: Partial<{ name: string; description: string; flavorText: string }>) => Promise<void>;
694	  onGamma: () => void;
695	}) {
696	  const { toast } = useToast();
697	  const updateAsset = useUpdateAsset();
698	  const qc = useQueryClient();
699	
700	  const [isEditing, setIsEditing] = useState(false);
701	  const [editForm, setEditForm] = useState({
702	    name: asset.name, kind: asset.kind, description: asset.description ?? "",
703	    flavorText: asset.flavorText ?? "", entityId: asset.entityId ? String(asset.entityId) : "",
704	  });
705	
706	  const [showEnhance, setShowEnhance] = useState(false);
707	  const [isEnhancing, setIsEnhancing] = useState(false);
708	  const [suggestion, setSuggestion] = useState<AssetEnhanceSuggestion | null>(null);
709	  const [picked, setPicked] = useState({ name: true, description: true, flavorText: true });
710	  const [applying, setApplying] = useState(false);
711	  const [applied, setApplied] = useState(false);
712	
713	  const linkedEntity = entities.find((e) => e.id === asset.entityId);
714	
715	  const saveEdit = async () => {
716	    try {
717	      await updateAsset.mutateAsync({
718	        projectId, assetId: asset.id,
719	        data: {
720	          name: editForm.name, kind: editForm.kind, description: editForm.description,
721	          flavorText: editForm.flavorText,
722	          ...(editForm.entityId ? { entityId: parseInt(editForm.entityId) } : { entityId: undefined }),
723	        },
724	      });
