730	    }
731	  };
732	
733	  const runEnhance = async () => {
734	    setIsEnhancing(true); setSuggestion(null); setApplied(false); setShowEnhance(true);
735	    try {
736	      const data = await fetchEnhance();
737	      setSuggestion(data);
738	      setPicked({
739	        name: !!data.name && data.name !== asset.name,
740	        description: !!data.description && data.description !== (asset.description ?? ""),
741	        flavorText: !!data.flavorText && data.flavorText !== (asset.flavorText ?? ""),
742	      });
743	    } catch (err) {
744	      toast({ title: "AI enhance failed", description: err instanceof Error ? err.message : String(err), variant: "destructive" });
745	      setShowEnhance(false);
746	    } finally {
747	      setIsEnhancing(false);
748	    }
749	  };
750	
751	  const handleApply = async () => {
752	    if (!suggestion) return;
753	    const fields: Partial<{ name: string; description: string; flavorText: string }> = {};
754	    if (picked.name && suggestion.name) fields.name = suggestion.name;
755	    if (picked.description && suggestion.description) fields.description = suggestion.description;
756	    if (picked.flavorText && suggestion.flavorText) fields.flavorText = suggestion.flavorText;
757	    if (!Object.keys(fields).length) { toast({ title: "Pick at least one field", variant: "destructive" }); return; }
758	    setApplying(true);
759	    try {
760	      await applyEnhance(fields);
761	      setApplied(true);
762	      toast({ title: "Asset updated" });
763	      setTimeout(() => { setShowEnhance(false); setSuggestion(null); setApplied(false); }, 1200);
764	    } catch (err) {
765	      toast({ title: "Apply failed", description: err instanceof Error ? err.message : String(err), variant: "destructive" });
766	    } finally {
767	      setApplying(false);
768	    }
769	  };
770	
771	  return (
772	    <Card className="bg-card border-card-border overflow-hidden flex flex-col group">
773	      {/* Image area */}
774	      <div className="aspect-square bg-muted/30 relative">
775	        {asset.imageDataUrl ? (
776	          <img src={asset.imageDataUrl} alt={asset.name} className="w-full h-full object-cover" />
777	        ) : (
778	          <div className="w-full h-full flex items-center justify-center">
779	            <ImageIcon className="h-12 w-12 text-muted-foreground opacity-20" />
780	          </div>
781	        )}
782	        <span className="absolute top-2 left-2 text-[10px] uppercase font-bold bg-black/60 text-white px-2 py-0.5 rounded">
783	          {asset.kind}
784	        </span>
785	        {linkedEntity && (
786	          <span className={`absolute bottom-2 left-2 text-[10px] font-semibold px-2 py-0.5 rounded border ${getMeta(linkedEntity.type).badge}`}>
787	            {getMeta(linkedEntity.type).icon} {linkedEntity.name}
788	          </span>
789	        )}
790	      </div>
791	
792	      {/* Info / edit */}
793	      <CardContent className="p-3 flex-1 flex flex-col gap-2">
794	        {isEditing ? (
795	          <div className="space-y-2">
796	            <Input value={editForm.name} onChange={(e) => setEditForm({ ...editForm, name: e.target.value })} className="h-8 text-sm font-semibold" autoFocus />
797	            <div className="grid grid-cols-2 gap-2">
798	              <Select value={editForm.kind} onValueChange={(v) => setEditForm({ ...editForm, kind: v })}>
799	                <SelectTrigger className="h-7 text-xs"><SelectValue /></SelectTrigger>
800	                <SelectContent>{ASSET_KINDS.map((k) => <SelectItem key={k} value={k}>{k}</SelectItem>)}</SelectContent>
801	              </Select>
802	              <Select value={editForm.entityId || "none"} onValueChange={(v) => setEditForm({ ...editForm, entityId: v === "none" ? "" : v })}>
803	                <SelectTrigger className="h-7 text-xs"><SelectValue placeholder="No entity" /></SelectTrigger>
804	                <SelectContent>
805	                  <SelectItem value="none">None</SelectItem>
806	                  {entities.map((e) => <SelectItem key={e.id} value={String(e.id)}>{getMeta(e.type).icon} {e.name}</SelectItem>)}
807	                </SelectContent>
808	              </Select>
809	            </div>
810	            <Textarea rows={2} placeholder="Description" value={editForm.description} onChange={(e) => setEditForm({ ...editForm, description: e.target.value })} className="text-xs resize-none" />
811	            <Textarea rows={2} placeholder="Flavor text / tag" value={editForm.flavorText} onChange={(e) => setEditForm({ ...editForm, flavorText: e.target.value })} className="text-xs resize-none" />
812	            <div className="flex gap-1.5">
813	              <Button size="sm" className="h-7 text-xs gap-1 flex-1" onClick={saveEdit} disabled={updateAsset.isPending}>
814	                {updateAsset.isPending ? <Loader2 className="h-3 w-3 animate-spin" /> : <Check className="h-3 w-3" />} Save
815	              </Button>
816	              <Button size="sm" variant="ghost" className="h-7 text-xs" onClick={() => setIsEditing(false)}>
817	                <X className="h-3 w-3" />
818	              </Button>
819	            </div>
820	          </div>
821	        ) : (
822	          <>
823	            <div className="flex items-start justify-between gap-1">
824	              <h3 className="font-semibold text-sm line-clamp-1 flex-1">{asset.name}</h3>
825	              <div className="flex gap-0.5 shrink-0">
826	                <Button variant="ghost" size="sm" className="h-6 px-1.5 text-[11px] gap-1 text-muted-foreground hover:text-primary" onClick={runEnhance} disabled={isEnhancing}>
827	                  {isEnhancing ? <Loader2 className="h-3 w-3 animate-spin" /> : <Wand2 className="h-3 w-3" />} AI
828	                </Button>
829	                <Button variant="ghost" size="sm" className="h-6 px-1.5 text-[11px] gap-1 text-muted-foreground hover:text-primary" onClick={onGamma} title="Generate PDF with Gamma">
830	                  <FileText className="h-3 w-3" /> Gamma
831	                </Button>
832	                <Button variant="ghost" size="icon" className="h-6 w-6 opacity-0 group-hover:opacity-100 text-muted-foreground hover:text-foreground" onClick={() => setIsEditing(true)}>
833	                  <Edit2 className="h-3 w-3" />
834	                </Button>
835	                <Button variant="ghost" size="icon" className="h-6 w-6 opacity-0 group-hover:opacity-100 text-muted-foreground hover:text-destructive" onClick={onDelete}>
836	                  <Trash2 className="h-3 w-3" />
837	                </Button>
838	              </div>
839	            </div>
840	            {asset.description && <p className="text-xs text-muted-foreground line-clamp-2">{asset.description}</p>}
841	            {asset.flavorText && <p className="text-xs text-muted-foreground/60 italic line-clamp-1">"{asset.flavorText}"</p>}
842	            <div className="flex gap-1.5 mt-auto pt-1">
843	              <Button size="sm" variant="outline" className="flex-1 h-7 text-xs gap-1" onClick={onGenerateImage} disabled={isGenerating}>
844	                <Sparkles className="h-3 w-3" /> {isGenerating ? "Generating…" : asset.imageDataUrl ? "Regen" : "Generate"}
845	              </Button>
846	              {asset.imageDataUrl && (
847	                <Button size="sm" variant="outline" className="h-7" onClick={onDownload}>
848	                  <Download className="h-3 w-3" />
849	                </Button>
850	              )}
851	            </div>
852	          </>
853	        )}
854	      </CardContent>
855	
856	      {/* AI enhance panel */}
857	      {showEnhance && (
858	        <div className="border-t border-border bg-primary/5 px-3 py-3 space-y-2">
859	          <div className="flex items-center gap-2">
860	            <Sparkles className="h-3.5 w-3.5 text-primary" />
861	            <p className="text-xs font-semibold text-primary flex-1">AI Enhancement</p>
862	            <button onClick={() => { setShowEnhance(false); setSuggestion(null); }} className="text-muted-foreground hover:text-white">
863	              <X className="h-3.5 w-3.5" />
864	            </button>
865	          </div>
866	          {isEnhancing && (
867	            <div className="flex items-center gap-2 text-xs text-muted-foreground py-1">
868	              <Loader2 className="h-3.5 w-3.5 animate-spin text-primary" /> Rewriting copy…
869	            </div>
870	          )}
871	          {suggestion && !isEnhancing && (
872	            <div className="space-y-2">
873	              <SuggestionField label="Name" current={asset.name} proposed={suggestion.name} checked={picked.name} onToggle={() => setPicked({ ...picked, name: !picked.name })} />
