894	
895	function EntitiesView({
896	  projectId, narrative, projectName, onGamma,
897	}: {
898	  projectId: number;
899	  narrative: string;
900	  projectName: string;
901	  onGamma: (title: string, prompt: string) => void;
902	}) {
903	  const queryClient = useQueryClient();
904	  const { data: entities, isLoading } = useListEntities(projectId);
905	  const createEntity = useCreateEntity();
906	  const deleteEntity = useDeleteEntity();
907	  const aiGenerate = useAiGenerateEntities();
908	  const { toast } = useToast();
909	
910	  const [aiPrompt, setAiPrompt] = useState("");
911	  const [aiCount, setAiCount] = useState(5);
912	  const [showAddForm, setShowAddForm] = useState(false);
913	  const [showAIPanel, setShowAIPanel] = useState(false);
914	  const [newEntity, setNewEntity] = useState<{
915	    name: string; type: ComponentType; subtype: string; description: string; parentEntityId?: number;
916	  }>({ name: "", type: "Card", subtype: "", description: "" });
917	  const [expandedIds, setExpandedIds] = useState<Set<number>>(new Set());
918	  const [collapsedGroups, setCollapsedGroups] = useState<Set<string>>(new Set());
919	  const [filterType, setFilterType] = useState("all");
920	
921	  const errMsg = (err: unknown) => err instanceof Error ? err.message : String(err);
922	  const refresh = () => queryClient.invalidateQueries({ queryKey: getListEntitiesQueryKey(projectId) });
923	
924	  const handleAiGenerate = async () => {
925	    if (!aiPrompt) return;
926	    try {
927	      await aiGenerate.mutateAsync({ projectId, data: { prompt: aiPrompt, count: aiCount } });
928	      setAiPrompt(""); setShowAIPanel(false); refresh();
929	      toast({ title: "Components generated" });
930	    } catch (err) {
931	      toast({ title: "AI generate failed", description: errMsg(err), variant: "destructive" });
932	    }
933	  };
934	
935	  const handleAddEntity = async (e: React.FormEvent) => {
936	    e.preventDefault();
937	    if (!newEntity.name) return;
938	    try {
939	      await createEntity.mutateAsync({
940	        projectId,
941	        data: { name: newEntity.name, type: newEntity.type, subtype: newEntity.subtype || undefined, description: newEntity.description || undefined, parentEntityId: newEntity.parentEntityId || undefined },
942	      });
943	      setNewEntity({ name: "", type: "Card", subtype: "", description: "" });
944	      setShowAddForm(false); refresh();
945	    } catch (err) {
946	      toast({ title: "Could not create component", description: errMsg(err), variant: "destructive" });
947	    }
948	  };
949	
950	  const handleDelete = async (id: number, name: string) => {
951	    if (!confirm(`Delete "${name}"?`)) return;
952	    try { await deleteEntity.mutateAsync({ projectId, entityId: id }); refresh(); }
953	    catch (err) { toast({ title: "Delete failed", description: errMsg(err), variant: "destructive" }); }
954	  };
955	
956	  const toggleExpand = (id: number) =>
957	    setExpandedIds((prev) => { const s = new Set(prev); s.has(id) ? s.delete(id) : s.add(id); return s; });
958	
959	  const toggleGroup = (type: string) =>
960	    setCollapsedGroups((prev) => { const s = new Set(prev); s.has(type) ? s.delete(type) : s.add(type); return s; });
961	
962	  const typeCounts = useMemo(() => {
963	    const out: Record<string, number> = {};
964	    (entities ?? []).forEach((e) => { out[e.type] = (out[e.type] || 0) + 1; });
965	    return out;
966	  }, [entities]);
967	
968	  const { topLevel, childrenByParent, decks } = useMemo(() => {
969	    const all = entities ?? [];
970	    const childrenByParent: Record<number, Entity[]> = {};
971	    const childIds = new Set<number>();
972	    all.forEach((e) => {
973	      if (e.parentEntityId) {
974	        childIds.add(e.id);
975	        if (!childrenByParent[e.parentEntityId]) childrenByParent[e.parentEntityId] = [];
976	        childrenByParent[e.parentEntityId].push(e);
977	      }
978	    });
979	    return { topLevel: all.filter((e) => !childIds.has(e.id)), childrenByParent, decks: new Set(all.filter((e) => e.type === "Deck").map((e) => e.id)) };
980	  }, [entities]);
981	
982	  const filtered = useMemo(() => filterType === "all" ? topLevel : topLevel.filter((e) => e.type === filterType), [topLevel, filterType]);
983	
984	  const grouped = useMemo(() => {
985	    if (filterType !== "all") return null;
986	    const map = new Map<string, Entity[]>();
987	    filtered.forEach((e) => { if (!map.has(e.type)) map.set(e.type, []); map.get(e.type)!.push(e); });
988	    return map;
989	  }, [filtered, filterType]);
990	
991	  const deckOptions = useMemo(() => (entities ?? []).filter((e) => e.type === "Deck"), [entities]);
992	
993	  return (
994	    <div className="space-y-4 pb-8">
995	      <div className="flex items-center justify-between flex-wrap gap-3">
996	        <p className="text-xs text-muted-foreground">
997	          {entities?.length ?? 0} components · use <span className="text-primary font-medium">Gamma</span> on any entity to generate a reference doc or PDF
998	        </p>
999	        <div className="flex gap-1.5">
1000	          <Button onClick={() => { setShowAIPanel(!showAIPanel); setShowAddForm(false); }} variant="outline" size="sm" className="h-8 border-primary/30 text-primary hover:bg-primary/10">
1001	            <Sparkles className="w-3.5 h-3.5 mr-1" /> AI Generate
1002	          </Button>
1003	          <Button onClick={() => { setShowAddForm(!showAddForm); setShowAIPanel(false); }} size="sm" className="h-8">
1004	            <Plus className="w-3.5 h-3.5 mr-1" /> Add Component
1005	          </Button>
1006	        </div>
1007	      </div>
1008	
1009	      {/* Filter pills */}
1010	      {entities && entities.length > 0 && (
1011	        <div className="space-y-1.5">
1012	          <div className="flex gap-1.5 flex-wrap">
1013	            <button onClick={() => setFilterType("all")} className={`text-xs px-2.5 py-1 rounded-full border transition-colors ${filterType === "all" ? "bg-white/10 text-white border-white/20" : "text-muted-foreground border-border hover:text-white"}`}>
1014	              All ({topLevel.length})
1015	            </button>
1016	            {PHYSICAL_TYPES.map((t) => { const c = typeCounts[t]; if (!c) return null; const m = getMeta(t); return (
1017	              <button key={t} onClick={() => setFilterType(t)} className={`text-xs px-2.5 py-1 rounded-full border transition-colors flex items-center gap-1 ${filterType === t ? m.badge : "text-muted-foreground border-border hover:text-white"}`}>
1018	                <span>{m.icon}</span> {t} ({c})
1019	              </button>
1020	            ); })}
1021	          </div>
1022	          <div className="flex gap-1.5 flex-wrap">
1023	            {WORLD_TYPES.map((t) => { const c = typeCounts[t]; if (!c) return null; const m = getMeta(t); return (
1024	              <button key={t} onClick={() => setFilterType(t)} className={`text-xs px-2.5 py-1 rounded-full border transition-colors flex items-center gap-1 ${filterType === t ? m.badge : "text-muted-foreground border-border hover:text-white"}`}>
1025	                <span>{m.icon}</span> {t} ({c})
1026	              </button>
1027	            ); })}
1028	          </div>
