1423	                    </div>
1424	                  )}
1425	                </div>
1426	              )}
1427	              {enhance.suggestedProperties.length > 0 && (
1428	                <div className="space-y-2">
1429	                  <div className="flex items-center justify-between">
1430	                    <p className={`text-xs font-semibold uppercase tracking-wider ${meta.color}`}>Suggested Properties ({enhance.suggestedProperties.length})</p>
1431	                    <div className="flex gap-2 text-xs">
1432	                      <button className="text-primary hover:underline" onClick={() => setSelectedProps(new Set(enhance.suggestedProperties.map((_, i) => i)))}>All</button>
1433	                      <button className="text-muted-foreground hover:underline" onClick={() => setSelectedProps(new Set())}>None</button>
1434	                    </div>
1435	                  </div>
1436	                  <div className="space-y-1.5">
1437	                    {enhance.suggestedProperties.map((prop, i) => {
1438	                      const isSel = selectedProps.has(i);
1439	                      return (
1440	                        <div key={i} className={`flex items-start gap-2.5 p-2.5 rounded-md border cursor-pointer transition-colors ${isSel ? "border-primary/40 bg-primary/5" : "border-border bg-muted/10"}`}
1441	                          onClick={() => setSelectedProps((prev) => { const n = new Set(prev); n.has(i) ? n.delete(i) : n.add(i); return n; })}>
1442	                          <div className={`w-4 h-4 rounded border-2 flex items-center justify-center shrink-0 mt-0.5 ${isSel ? "border-primary bg-primary" : "border-border"}`}>
