1448	                              <Badge variant="outline" className="text-[10px] font-mono bg-secondary/30">{prop.dataType}</Badge>
1449	                              {prop.defaultValue != null && prop.defaultValue !== "" && <span className="text-xs text-muted-foreground font-mono">= {prop.defaultValue}</span>}
