1459	              <div className="flex items-center gap-2 pt-1 flex-wrap">
1460	                <Button onClick={handleApply} disabled={applying || applied} size="sm" className="bg-primary text-primary-foreground">
1461	                  {applied ? <><Check className="w-3.5 h-3.5 mr-1.5" />Applied!</> : applying ? <><Loader2 className="w-3.5 h-3.5 animate-spin mr-1.5" />Applying…</> : <><Wand2 className="w-3.5 h-3.5 mr-1.5" />Apply{selectedProps.size > 0 ? ` + ${selectedProps.size} Props` : ""}</>}
1462	                </Button>
