1487	                  <p className="text-xs text-muted-foreground leading-relaxed bg-background/40 border border-border/50 rounded p-2.5 whitespace-pre-wrap">{entity.designNotes}</p>
1488	                </div>
1489	              )}
1490	            </div>
1491	          )}
1492	          {isDeck && (
1493	            <div className="space-y-2">
1494	              <div className="flex items-center justify-between">
1495	                <p className="text-[10px] font-semibold text-muted-foreground uppercase tracking-wider flex items-center gap-1.5">
