1525	// ── Entity properties ─────────────────────────────────────────────────────────
1526	
1527	const PROP_TYPES = ["number", "string", "boolean", "enum"] as const;
1528	
1529	function EntityProperties({ projectId, entityId }: { projectId: number; entityId: number }) {
1530	  const queryClient = useQueryClient();
1531	  const { data: properties, isLoading } = useListEntityProperties(projectId, entityId);
1532	  const createProperty = useCreateEntityProperty();
1533	  const updateProperty = useUpdateEntityProperty();
1534	  const deleteProperty = useDeleteEntityProperty();
1535	  const { toast } = useToast();
1536	
1537	  const [newProp, setNewProp] = useState({ name: "", dataType: "number", defaultValue: "" });
1538	  const [editingId, setEditingId] = useState<number | null>(null);
1539	  const [editProp, setEditProp] = useState({ name: "", dataType: "number", defaultValue: "" });
1540	
1541	  const errMsg = (err: unknown) => err instanceof Error ? err.message : String(err);
1542	  const refresh = () => queryClient.invalidateQueries({ queryKey: getListEntityPropertiesQueryKey(projectId, entityId) });
1543	
1544	  const valueToPayload = (val: string) => {
1545	    if (val === "") return { textValue: "" };
1546	    const num = Number(val);
1547	    if (Number.isFinite(num) && val.trim() !== "") return { defaultValue: num, textValue: "" };
1548	    return { textValue: val, defaultValue: undefined };
1549	  };
1550	
1551	  const displayValue = (p: EntityProperty) => {
1552	    if (p.defaultValue != null) return String(p.defaultValue);
1553	    if (p.textValue) return p.textValue;
1554	    if (p.value != null) return String(p.value);
1555	    return "—";
1556	  };
1557	
1558	  const handleAddProp = async (e: React.FormEvent) => {
1559	    e.preventDefault();
1560	    if (!newProp.name) return;
1561	    try {
1562	      await createProperty.mutateAsync({ projectId, entityId, data: { name: newProp.name, dataType: newProp.dataType, ...valueToPayload(newProp.defaultValue) } });
1563	      setNewProp({ name: "", dataType: "number", defaultValue: "" }); refresh();
1564	    } catch (err) { toast({ title: "Could not add property", description: errMsg(err), variant: "destructive" }); }
1565	  };
1566	
1567	  const startEdit = (prop: EntityProperty) => {
1568	    setEditingId(prop.id);
1569	    setEditProp({ name: prop.name, dataType: prop.dataType, defaultValue: displayValue(prop) === "—" ? "" : displayValue(prop) });
1570	  };
1571	
1572	  const saveEdit = async () => {
1573	    if (!editingId) return;
1574	    try {
1575	      await updateProperty.mutateAsync({ projectId, entityId, propertyId: editingId, data: { name: editProp.name, dataType: editProp.dataType, ...valueToPayload(editProp.defaultValue) } });
1576	      setEditingId(null); refresh();
1577	    } catch (err) { toast({ title: "Could not update property", description: errMsg(err), variant: "destructive" }); }
1578	  };
1579	
1580	  const handleDelete = async (id: number) => {
1581	    try { await deleteProperty.mutateAsync({ projectId, entityId, propertyId: id }); refresh(); }
1582	    catch (err) { toast({ title: "Could not delete property", description: errMsg(err), variant: "destructive" }); }
1583	  };
1584	
1585	  if (isLoading) return <div className="text-sm text-muted-foreground py-1">Loading properties…</div>;
1586	
1587	  return (
1588	    <div className="space-y-3">
1589	      <div className="flex items-center gap-2 text-xs font-semibold text-muted-foreground uppercase tracking-wider">
1590	        <Settings className="w-3.5 h-3.5" /> Properties
1591	        {properties && properties.length > 0 && <span className="text-muted-foreground/50 font-normal normal-case tracking-normal ml-1">— click row to edit</span>}
1592	      </div>
1593	      {properties && properties.length > 0 && (
1594	        <div className="rounded-md border border-border overflow-hidden">
1595	          <div className="grid grid-cols-12 gap-3 px-3 py-2 text-[10px] font-semibold text-muted-foreground uppercase tracking-wider bg-muted/20 border-b border-border">
1596	            <div className="col-span-4">Name</div><div className="col-span-3">Type</div><div className="col-span-3">Default</div><div className="col-span-2" />
1597	          </div>
1598	          {properties.map((prop) => (
1599	            <div key={prop.id} className="border-b border-border/40 last:border-0">
1600	              {editingId === prop.id ? (
1601	                <div className="grid grid-cols-12 gap-2 px-3 py-2 items-center bg-primary/5 border-l-2 border-primary">
1602	                  <div className="col-span-4"><Input value={editProp.name} onChange={(e) => setEditProp((p) => ({ ...p, name: e.target.value }))} className="h-7 text-xs bg-input font-mono" autoFocus /></div>
1603	                  <div className="col-span-3">
1604	                    <Select value={editProp.dataType} onValueChange={(v) => setEditProp((p) => ({ ...p, dataType: v }))}>
1605	                      <SelectTrigger className="h-7 text-xs bg-input"><SelectValue /></SelectTrigger>
1606	                      <SelectContent>{PROP_TYPES.map((t) => <SelectItem key={t} value={t}>{t}</SelectItem>)}</SelectContent>
1607	                    </Select>
1608	                  </div>
1609	                  <div className="col-span-3"><Input value={editProp.defaultValue} onChange={(e) => setEditProp((p) => ({ ...p, defaultValue: e.target.value }))} className="h-7 text-xs bg-input font-mono" placeholder="default" /></div>
1610	                  <div className="col-span-2 flex items-center justify-end gap-1">
1611	                    <button onClick={saveEdit} disabled={updateProperty.isPending} className="text-primary hover:text-primary/80 p-1 disabled:opacity-50">
1612	                      {updateProperty.isPending ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Check className="w-3.5 h-3.5" />}
1613	                    </button>
1614	                    <button onClick={() => setEditingId(null)} className="text-muted-foreground hover:text-white p-1"><X className="w-3.5 h-3.5" /></button>
1615	                  </div>
1616	                </div>
1617	              ) : (
1618	                <div className="grid grid-cols-12 gap-3 px-3 py-2 items-center text-sm hover:bg-muted/10 cursor-pointer group" onClick={() => startEdit(prop)}>
1619	                  <div className="col-span-4 font-mono text-xs text-white truncate">{prop.name}</div>
1620	                  <div className="col-span-3"><Badge variant="secondary" className="bg-secondary/40 font-mono text-[10px]">{prop.dataType}</Badge></div>
1621	                  <div className="col-span-3 text-muted-foreground font-mono text-xs truncate">{displayValue(prop)}</div>
1622	                  <div className="col-span-2 flex items-center justify-end gap-1 opacity-0 group-hover:opacity-100">
1623	                    <button onClick={(e) => { e.stopPropagation(); startEdit(prop); }} className="text-muted-foreground hover:text-white p-0.5"><Pencil className="w-3 h-3" /></button>
1624	                    <button onClick={(e) => { e.stopPropagation(); handleDelete(prop.id); }} className="text-muted-foreground hover:text-destructive p-0.5"><Trash2 className="w-3 h-3" /></button>
1625	                  </div>
1626	                </div>
1627	              )}
1628	            </div>
1629	          ))}
1630	        </div>
1631	      )}
1632	      {(!properties || properties.length === 0) && <p className="text-xs text-muted-foreground/60 py-1">No properties yet.</p>}
1633	      <form onSubmit={handleAddProp} className="flex gap-2 items-end">
1634	        <div className="flex-1 space-y-1">
1635	          <Label className="text-[10px] text-muted-foreground uppercase tracking-wider">Property Name</Label>
