1637	        </div>
1638	        <div className="w-32 space-y-1">
1639	          <Label className="text-[10px] text-muted-foreground uppercase tracking-wider">Type</Label>
1640	          <Select value={newProp.dataType} onValueChange={(v) => setNewProp({ ...newProp, dataType: v })}>
1641	            <SelectTrigger className="h-8 text-xs bg-input"><SelectValue /></SelectTrigger>
1642	            <SelectContent>{PROP_TYPES.map((t) => <SelectItem key={t} value={t}>{t}</SelectItem>)}</SelectContent>
1643	          </Select>
1644	        </div>
1645	        <div className="w-28 space-y-1">
1646	          <Label className="text-[10px] text-muted-foreground uppercase tracking-wider">Default</Label>
1647	          <Input className="h-8 text-xs bg-input font-mono" placeholder="0" value={newProp.defaultValue} onChange={(e) => setNewProp({ ...newProp, defaultValue: e.target.value })} />
1648	        </div>
1649	        <Button size="sm" className="h-8 shrink-0" type="submit" disabled={createProperty.isPending || !newProp.name}>
1650	          {createProperty.isPending ? <Loader2 className="w-3.5 h-3.5 mr-1 animate-spin" /> : <Plus className="w-3.5 h-3.5 mr-1" />}Add
1651	        </Button>
1652	      </form>
1653	    </div>
1654	  );
1655	}
1656	
1657	// ── Suggestion field (asset AI enhance) ───────────────────────────────────────
1658	
1659	function SuggestionField({ label, current, proposed, checked, onToggle }: {
1660	  label: string; current: string; proposed?: string; checked: boolean; onToggle: () => void;
1661	}) {
1662	  if (!proposed || proposed === current) {
1663	    return (
1664	      <div className="space-y-1">
1665	        <p className="text-[10px] font-semibold text-muted-foreground uppercase tracking-wider">{label}</p>
1666	        <p className="text-xs text-muted-foreground italic">{!proposed ? "No change suggested." : "No change — AI returned same value."}</p>
1667	      </div>
1668	    );
1669	  }
1670	  return (
1671	    <div className="space-y-1.5">
1672	      <div className="flex items-center justify-between">
1673	        <p className="text-[10px] font-semibold text-muted-foreground uppercase tracking-wider">{label}</p>
1674	        <label className="flex items-center gap-1.5 text-[11px] text-muted-foreground cursor-pointer select-none">
1675	          <input type="checkbox" checked={checked} onChange={onToggle} className="h-3 w-3 accent-primary" />
1676	          Apply this
1677	        </label>
1678	      </div>
1679	      {current && <p className="text-xs text-muted-foreground/70 line-through bg-background/40 border border-border rounded px-2 py-1">{current}</p>}
1680	      <p className={`text-xs leading-relaxed bg-background/60 border rounded px-2 py-1.5 ${checked ? "text-foreground border-primary/40" : "text-muted-foreground border-border"}`}>{proposed}</p>
1681	    </div>
1682	  );
1683	}
